INSERT INTO "ToolRegistryEntry" ("id", "tool_id", "label", "label_hi", "text", "chat_guidable", "kind", "summary", "summary_hi", "section", "therapy_modality", "therapist_note", "access_mode", "load_level", "est_minutes", "content_en", "content_hi", "status", "approved_at", "sort_order", "library_group", "care_plans", "sensitive_check", "updated_at") VALUES
    ('c1b2a3d4-0000-4e00-9000-0000000003e9', 'ws_whats_on_my_plate', 'What''s on my plate', NULL, 'Put everything down in one place, then decide what can wait.', false, 'worksheet', 'Put everything down in one place, then decide what can wait.', NULL, 'do_what_matters', 'Task triage (behavioural activation / stress management)', 'sorts current demands into must do / can wait / can drop or hand off. Light on purpose, so it stays usable on an overwhelmed day.', 'open', 'light', 5, $ws_ws_whats_on_my_plate${"version":1,"intro":"When everything is in your head at once, it can all feel equally urgent. Writing it down helps you see what's actually there — and what can wait.","fields":[{"id":"tasks","type":"row_list","prompt":"What's on your plate right now?","helper":"One thing per line. Anything counts — big, small, work, home, the message you keep meaning to send.","maxRows":10,"addLabel":"Add another","columns":[{"id":"task","label":"What","type":"text"},{"id":"plan","label":"What I'll do with it","type":"choice","options":[{"value":"must_do","label":"Must do"},{"value":"can_wait","label":"Can wait"},{"value":"can_drop","label":"Can drop or hand off"}]}]},{"id":"noticed","type":"closing_reflection","prompt":"Was anything easier to decide once you saw it written down?","helper":"There's no right answer. This is just for you."}],"closing":{"text":"You don't have to do all of it. Deciding what can wait is part of the work."}}$ws_ws_whats_on_my_plate$::jsonb, NULL, 'draft', NULL, 30, NULL, ARRAY['stress_burnout']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003ea', 'ws_basics_check', 'Basics check', NULL, 'A quick look at the everyday basics, and one to look after today.', false, 'worksheet', 'A quick look at the everyday basics, and one to look after today.', NULL, 'energy_life', 'Psychoeducation: the everyday basics under load', 'sleep, food, movement, rest, daylight and contact. Ticks only, no quantities, so it cannot become a food or body record. The slider is read as the client''s own number, never a band.', 'open', 'light', 3, $ws_ws_basics_check${"version":1,"intro":"When you're running on empty, the basics are usually the first to go — and the hardest to notice. This is a quick look, not a test.","fields":[{"id":"basics","type":"checklist","prompt":"Which of these have you had in the last day or two?","helper":"Tick what's true. Nothing here is graded.","options":[{"value":"slept","label":"slept enough"},{"value":"ate","label":"ate proper meals"},{"value":"moved","label":"moved my body"},{"value":"break","label":"took a break"},{"value":"outside","label":"went outside"},{"value":"talked","label":"talked to someone"}]},{"id":"tank","type":"scale_0_10","prompt":"How empty does my tank feel?","minLabel":"0 = full","maxLabel":"10 = running on empty"},{"id":"one_basic","type":"short_text","prompt":"One basic I'll look after today","helper":"Pick the easiest one, not the most important one.","example":"Go to bed by eleven. Text my sister back."}],"closing":{"text":"One basic, done today, is worth more than a perfect plan for next week."}}$ws_ws_basics_check$::jsonb, NULL, 'draft', NULL, 20, NULL, ARRAY['stress_burnout']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003eb', 'ws_rest_break', 'Rest break', NULL, 'Stop for a few minutes on purpose, with nothing to show for it.', false, 'worksheet', 'Stop for a few minutes on purpose, with nothing to show for it.', NULL, 'calm_my_body', 'Rest as a skill (nervous-system down-regulation)', 'a timed stop with no productivity attached. The timer stores the seconds it actually ran; stopping early is a complete answer, so there is no minimum.', 'open', 'light', 5, $ws_ws_rest_break${"version":1,"intro":"Rest is not a reward you earn after everything else is done. It's part of how you keep going.","fields":[{"id":"length","type":"choice","prompt":"How long do you want to stop for?","required":true,"options":[{"value":"two","label":"2 minutes"},{"value":"five","label":"5 minutes"},{"value":"ten","label":"10 minutes"}]},{"id":"rest_two","type":"countdown_timer","prompt":"You have permission to stop. Nothing needs to be earned first.","helper":"Sit, lie down, look out of the window. Doing nothing is the point.","seconds":120,"startLabel":"Start the 2 minutes","doneLabel":"Time's up","visibleWhen":{"field":"length","in":["two"]}},{"id":"rest_five","type":"countdown_timer","prompt":"You have permission to stop. Nothing needs to be earned first.","helper":"Put the phone down if you can. The world will still be there after.","seconds":300,"startLabel":"Start the 5 minutes","doneLabel":"Time's up","visibleWhen":{"field":"length","in":["five"]}},{"id":"rest_ten","type":"countdown_timer","prompt":"You have permission to stop. Nothing needs to be earned first.","helper":"Ten minutes is a real rest, not a long one. You can stop earlier if you want.","seconds":600,"startLabel":"Start the 10 minutes","doneLabel":"Time's up","visibleWhen":{"field":"length","in":["ten"]}},{"id":"after","type":"closing_reflection","prompt":"Anything different after stopping for a moment?","helper":"Optional. A word is enough."}],"closing":{"text":"Stopping is a skill. You just practised it."}}$ws_ws_rest_break$::jsonb, NULL, 'draft', NULL, 30, NULL, ARRAY['stress_burnout']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003ec', 'ws_boundary_planner', 'Boundary planner', NULL, 'Work out what you want to say no to, and the words to say it.', false, 'worksheet', 'Work out what you want to say no to, and the words to say it.', NULL, 'people_boundaries', 'Assertiveness and boundary setting', 'prepares one boundary sentence before it is needed. Assigned, because a boundary is usually rehearsed in session first.', 'assigned', 'light', 10, $ws_ws_boundary_planner${"version":1,"intro":"A boundary is a sentence about what you can and can't do. It's easier to say when you've decided the words before you need them.","fields":[{"id":"situation","type":"short_text","prompt":"What's the situation?","helper":"A few words is enough.","example":"My manager keeps adding work at 7pm."},{"id":"who","type":"short_text","prompt":"Who is it with?","helper":"A name, a role, or just 'someone at home'."},{"id":"no_to","type":"short_text","prompt":"What do you want to say no to?","example":"Taking on another project this month."},{"id":"words","type":"long_text","prompt":"What will you say? Write it the way you'd actually say it.","helper":"Short and plain usually works better than a speech. You can change it after you've said it out loud once.","example":"I can't take another project this month. I can start it in December."},{"id":"hard","type":"scale_0_10","prompt":"How hard does this feel to say?","minLabel":"0 = easy","maxLabel":"10 = very hard"},{"id":"helps","type":"closing_reflection","prompt":"What would make it a little easier to say?","helper":"Where you say it, who is nearby, what you do straight afterwards."}],"closing":{"text":"You're allowed to take up space in your own life."}}$ws_ws_boundary_planner$::jsonb, NULL, 'draft', NULL, 20, NULL, ARRAY['stress_burnout']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003ed', 'ws_priority_sorter', 'Priority sorter', NULL, 'Sort what you are carrying into four boxes, then pick one to start.', false, 'worksheet', 'Sort what you are carrying into four boxes, then pick one to start.', NULL, 'do_what_matters', 'Prioritisation (urgent / important)', 'one list, one label per line, then a single first step. Urgent is about time; important is about what matters to the client.', 'assigned', 'light', 5, $ws_ws_priority_sorter${"version":1,"intro":"Not everything urgent is important, and not everything important is urgent. Sorting it takes a minute and saves a lot.","fields":[{"id":"tasks","type":"row_list","prompt":"Add the things you're carrying.","helper":"Urgent means it needs doing soon. Important means it matters to you. Most things are only one of the two.","maxRows":10,"addLabel":"Add another","columns":[{"id":"task","label":"What","type":"text"},{"id":"box","label":"Which box","type":"choice","options":[{"value":"urgent_important","label":"Urgent and important"},{"value":"important_not_urgent","label":"Important, not urgent"},{"value":"urgent_not_important","label":"Urgent, not important"},{"value":"neither","label":"Neither"}]}]},{"id":"first","type":"short_text","prompt":"Which one will you do first?","helper":"One only. The rest can wait their turn."}],"closing":{"text":"You don't have to do it all today. You just have to know what's first."}}$ws_ws_priority_sorter$::jsonb, NULL, 'draft', NULL, 40, NULL, ARRAY['stress_burnout']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003ee', 'ws_scrolling_log', 'Doomscroll log', NULL, 'Note when you scrolled, how long, and how it felt before and after.', false, 'worksheet', 'Note when you scrolled, how long, and how it felt before and after.', NULL, 'energy_life', 'Digital habits: behavioural chain', 'before-and-after feelings around a scrolling episode, to show what the scrolling is doing for the client. Carries the deeper screen (owner, 24 Nov 2026).', 'open', 'light', 3, $ws_ws_scrolling_log${"version":1,"intro":"Scrolling isn't a moral failure. It's easier to change when you can see what it does for you — and what it costs.","fields":[{"id":"when","type":"datetime","prompt":"When did this happen?","withDate":true,"withTime":true},{"id":"how_long","type":"choice","prompt":"How long were you scrolling?","options":[{"value":"under_15","label":"Under 15 minutes"},{"value":"15_to_60","label":"15–60 minutes"},{"value":"over_hour","label":"Over an hour"}]},{"id":"before","type":"feelings_picker","prompt":"How did you feel just before you picked up your phone?","maxSelections":3,"feelings":[{"id":"sad","label":"sad"},{"id":"scared","label":"scared"},{"id":"angry","label":"angry"},{"id":"ashamed","label":"ashamed"},{"id":"happy","label":"happy"},{"id":"calm","label":"calm"},{"id":"numb","label":"numb"},{"id":"worried","label":"worried","parent":"scared"},{"id":"panicky","label":"panicky","parent":"scared"},{"id":"unsafe","label":"unsafe","parent":"scared"},{"id":"on_edge","label":"on edge","parent":"scared"}]},{"id":"after","type":"feelings_picker","prompt":"And afterwards?","maxSelections":3,"feelings":[{"id":"sad","label":"sad"},{"id":"scared","label":"scared"},{"id":"angry","label":"angry"},{"id":"ashamed","label":"ashamed"},{"id":"happy","label":"happy"},{"id":"calm","label":"calm"},{"id":"numb","label":"numb"},{"id":"worried","label":"worried","parent":"scared"},{"id":"panicky","label":"panicky","parent":"scared"},{"id":"unsafe","label":"unsafe","parent":"scared"},{"id":"on_edge","label":"on edge","parent":"scared"}]},{"id":"pulled_in","type":"short_text","prompt":"What pulled you in?","helper":"Boredom, a notification, a feeling you didn't want, a habit. All of these count."}],"closing":{"text":"Noticing is the whole exercise. Nothing here has to be different next time."}}$ws_ws_scrolling_log$::jsonb, NULL, 'draft', NULL, 30, NULL, ARRAY['stress_burnout']::TEXT[], true, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003ef', 'ws_weekly_load_check', 'Weekly load check', NULL, 'Look at how much you carried this week, and what it was made of.', false, 'worksheet', 'Look at how much you carried this week, and what it was made of.', NULL, 'energy_life', 'Weekly load review', 'one number for the week and the demands behind it. Past weeks read as a plain list in Past me — no graph, no score, no trend language.', 'assigned', 'light', 5, $ws_ws_weekly_load_check${"version":1,"intro":"Once a week, it helps to look at how much you were carrying — not to judge it, just to see it.","fields":[{"id":"load","type":"scale_0_10","prompt":"How heavy did this week feel?","minLabel":"0 = light","maxLabel":"10 = as heavy as it gets"},{"id":"demands","type":"row_list","prompt":"What were the biggest things you carried this week?","helper":"Work, people, money, health, things you kept saying you would do.","maxRows":6,"addLabel":"Add another","columns":[{"id":"demand","label":"What","type":"text"}]},{"id":"noticed","type":"closing_reflection","prompt":"What do you notice, looking at this week?","helper":"You can see your past weeks in Past me, under this worksheet."}],"closing":{"text":"However heavy the week was, you carried it. That counts."}}$ws_ws_weekly_load_check$::jsonb, NULL, 'draft', NULL, 40, NULL, ARRAY['stress_burnout']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003f0', 'ws_unsent_letter', 'Unsent letter', NULL, 'Write what was never said, then choose whether to keep it.', false, 'worksheet', 'Write what was never said, then choose whether to keep it.', NULL, 'people_boundaries', 'Expressive writing (unsent letter)', 'high load. Carries the deeper screen. The client chooses keep or delete at the end; delete removes the saved entry at once, and only the content-free flag stays.', 'assigned', 'demanding', 15, $ws_ws_unsent_letter${"version":1,"intro":"Some things never got said, and maybe they never will. Writing them down, with no plan to send them, can make a little more room inside you.","fields":[{"id":"to","type":"short_text","prompt":"Who is this letter to?","helper":"A name, a relationship, or just 'someone I used to know'. You don't have to explain."},{"id":"letter","type":"long_text","prompt":"Write the letter.","helper":"Say the whole thing. Nobody reads this unless you choose to share it. You can type it or speak it."},{"id":"keep","type":"choice","prompt":"What would you like to do with it now?","required":true,"helper":"Keeping it saves it in Past me, private unless you share it later. Deleting removes it straight away.","options":[{"value":"keep","label":"Keep it privately"},{"value":"delete","label":"Delete it"}]}],"closing":{"text":"You wrote it, and you decided what happens to it. Both of those are yours.","discardWhen":{"field":"keep","in":["delete"]}}}$ws_ws_unsent_letter$::jsonb, NULL, 'draft', NULL, 30, NULL, ARRAY['stress_burnout']::TEXT[], true, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003f1', 'ws_pros_cons_change', 'Weighing it up', NULL, 'Look at both sides of changing, and of staying the same.', false, 'worksheet', 'Look at both sides of changing, and of staying the same.', NULL, 'do_what_matters', 'Motivational interviewing: decisional balance', 'the four-quadrant decisional balance, plus a readiness rating. Values are read as the client''s own words; nothing is counted.', 'assigned', 'light', 10, $ws_ws_pros_cons_change${"version":1,"intro":"When part of you wants to change and part of you doesn't, that's not a flaw. It's worth looking at both sides slowly.","fields":[{"id":"good_changing","type":"long_text","prompt":"What might be good about changing?","helper":"Even small good things. Nothing is too obvious."},{"id":"good_same","type":"long_text","prompt":"What might be good about staying the same?","helper":"There's usually something, or it would be easier to change."},{"id":"cost_changing","type":"long_text","prompt":"What might changing cost you?","helper":"Time, comfort, people, the way things are now."},{"id":"cost_same","type":"long_text","prompt":"What might staying the same cost you?","helper":"It's alright if this is hard to answer. Take your time."},{"id":"ready","type":"scale_0_10","prompt":"How ready do you feel to change, right now?","helper":"There's no right number. Ready moves.","minLabel":"0 = not at all","maxLabel":"10 = completely"},{"id":"noticed","type":"closing_reflection","prompt":"What do you notice, seeing all four side by side?","helper":"Optional."}],"closing":{"text":"Noticing both sides is not the same as staying stuck."}}$ws_ws_pros_cons_change$::jsonb, NULL, 'draft', NULL, 50, NULL, ARRAY['stress_burnout']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-0000000003f2', 'ws_caring_load_check', 'Caring load check', NULL, 'Name the caring you carry, and one bit of help you could ask for.', false, 'worksheet', 'Name the caring you carry, and one bit of help you could ask for.', NULL, 'energy_life', 'Carer load (psychoeducation)', 'names care work that often goes uncounted, then asks for one concrete ask. No quantities and no score.', 'assigned', 'light', 5, $ws_ws_caring_load_check${"version":1,"intro":"Looking after other people is real work, even when nobody counts it as work. This is a place to put it down for a minute.","fields":[{"id":"caring","type":"checklist","prompt":"Which of these are you carrying at the moment?","helper":"Tick as many as are true. Some of them are easy to miss.","options":[{"value":"family_member","label":"looking after a family member"},{"value":"household","label":"the household"},{"value":"money","label":"money and bills"},{"value":"emotional","label":"emotional support for someone"},{"value":"admin","label":"appointments and paperwork"},{"value":"other","label":"something else"}]},{"id":"stretched","type":"scale_0_10","prompt":"How stretched do you feel?","minLabel":"0 = I have room","maxLabel":"10 = there is nothing left"},{"id":"help","type":"short_text","prompt":"One bit of help you could ask for","helper":"It can be small. Someone else making dinner once. An hour to yourself."}],"closing":{"text":"Asking for help is part of caring, not a break from it."}}$ws_ws_caring_load_check$::jsonb, NULL, 'draft', NULL, 50, NULL, ARRAY['stress_burnout']::TEXT[], false, CURRENT_TIMESTAMP)
